export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const m = inputs.mass;

  const tTop = u / g;
  const tMax = 2 * tTop;
  const clampedT = Math.min(Math.max(time, 0), tMax);

  const v = u - g * clampedT;
  const a = -g;
  const F = m * g;
  const y = u * clampedT - 0.5 * g * clampedT * clampedT;
  const yTop = (u * u) / (2 * g);

  let stateText = "Ready to toss";
  if (clampedT > 0 && clampedT < tTop - 0.02) {
    stateText = "Rising";
  } else if (Math.abs(clampedT - tTop) <= 0.02) {
    stateText = "At the top";
  } else if (clampedT > tTop + 0.02 && clampedT < tMax - 0.001) {
    stateText = "Falling";
  } else if (clampedT >= tMax - 0.001) {
    stateText = "Back at launch height";
  }

  const objects = [];

  // Panel 1: Motion
  const panelLeft = sdk.panel({
    x: 20,
    y: 35,
    w: 280,
    h: 365,
    title: "The motion",
    state: stateText,
    id: "lane.toss"
  });
  objects.push(...panelLeft);

  // Axis inside left panel
  const yAxis = sdk.axis("axis.y", {
    x: 80,
    y: 360,
    length: 290,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  });
  objects.push(yAxis);

  // Ball
  const ballX = 140;
  const pixelY = 360 - (y / 2.2) * 290;
  const ballObj = sdk.circle("ball.toss", ballX, pixelY, 28);
  objects.push(ballObj);

  // Velocity Arrow (blue)
  const vScale = 18;
  const vVec = sdk.vector("vec.v", { x: ballX + 22, y: pixelY }, {
    value: v,
    direction: "up",
    scale: vScale,
    label: "v",
    role: "output"
  });
  objects.push(...vVec);

  // Acceleration Arrow (warm/dashed concept -> represented via role/vector)
  const aScale = 6;
  const aVec = sdk.vector("vec.a", { x: ballX - 22, y: pixelY }, {
    value: a,
    direction: "up",
    scale: aScale,
    label: "a",
    role: "warning"
  });
  objects.push(...aVec);

  // Callout beside ball
  const vFormatted = (v >= 0 ? "+" : "") + sdk.format(v, 2) + " m/s";
  const aFormatted = sdk.format(a, 2) + " m/s²";
  const fFormatted = sdk.format(F, 1) + " N (down)";
  const calloutObj = sdk.callout(
    ballX + 45,
    pixelY - 30,
    [
      "v: " + vFormatted,
      "a: " + aFormatted,
      "Fg: " + fFormatted
    ],
    { id: "callout.toss" }
  );
  objects.push(...calloutObj);

  // Panel 2: Velocity Plot
  const panelRight = sdk.panel({
    x: 320,
    y: 35,
    w: 300,
    h: 365,
    title: "Velocity over time",
    state: "v = u - g t",
    id: "lane.vt"
  });
  objects.push(...panelRight);

  const plotX = 350;
  const plotY = 65;
  const plotW = 250;
  const plotH = 310;

  // Sample points for series
  const currentPoints = [];
  const futurePoints = [];
  const numSamples = 20;
  for (let i = 0; i <= numSamples; i++) {
    const tVal = (i / numSamples) * 1.8;
    const vVal = u - g * tVal;
    const pt = { x: tVal, y: vVal };
    if (tVal <= clampedT + 0.001) {
      currentPoints.push(pt);
    } else {
      futurePoints.push(pt);
    }
  }
  if (currentPoints.length > 0 && futurePoints.length > 0) {
    futurePoints.unshift(currentPoints[currentPoints.length - 1]);
  }

  const plotObj = sdk.plot("plot.vt", {
    x: plotX,
    y: plotY,
    w: plotW,
    h: plotH,
    axes: {
      x: { label: "Time", min: 0, max: 1.8, unit: "s" },
      y: { label: "Velocity", min: -5.5, max: 5.5, unit: "m/s" }
    },
    series: [
      { label: "v(t)", kind: "line", points: currentPoints },
      { label: "future", kind: "line", points: futurePoints }
    ]
  });
  objects.push(plotObj);

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "velocity", value: v },
        { id: "acceleration", value: a },
        { id: "force", value: F },
        { id: "motionState", value: stateText }
      ]
    },
    quantities: {
      launchSpeed: u,
      gravity: g,
      mass: m,
      apexTime: tTop,
      apexHeight: yTop,
      height: y,
      velocity: v,
      acceleration: a,
      force: F
    }
  };
}
